package app.moire.anniversary;
import android.os.Bundle;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.media.RingtoneManager;import android.net.Uri;import android.app.AlarmManager;import android.provider.Settings;import com.getcapacitor.BridgeActivity;
public class MainActivity extends BridgeActivity {
 @Override public void onCreate(Bundle state){super.onCreate(state);getBridge().getWebView().addJavascriptInterface(new MoireWidget.Bridge(this),"MoireNative");if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},2301);if(android.os.Build.VERSION.SDK_INT>=31){AlarmManager a=(AlarmManager)getSystemService(ALARM_SERVICE);if(!a.canScheduleExactAlarms()){try{startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}catch(Exception ignored){}}}}
 @Override public void onResume(){super.onResume();MoireWidget.refresh(this);MoireAlarm.scheduleAll(this);}
 public void chooseSound(){Intent i=new Intent(RingtoneManager.ACTION_RINGTONE_PICKER);i.putExtra(RingtoneManager.EXTRA_RINGTONE_TYPE,RingtoneManager.TYPE_ALARM);i.putExtra(RingtoneManager.EXTRA_RINGTONE_SHOW_SILENT,false);startActivityForResult(i,2402);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==2402&&result==RESULT_OK&&data!=null){Uri uri=data.getParcelableExtra(RingtoneManager.EXTRA_RINGTONE_PICKED_URI);if(uri!=null)getSharedPreferences(MoireAlarm.PREF,0).edit().putString("sound_uri",uri.toString()).apply();}}
}
